# managed-by: personal-multi-harness-workstation-configuration; source: global/install.sh (paste wrapper, ADR-0011); release: <RELEASE>; commit: <COMMIT>; do not edit, re-run the installer
# The paste filter at the harness-CLI paste boundary (ADR-0011). install.sh sources it from a
# managed block in your shell start-up file (~/.zshrc, or ~/.bashrc and on macOS ~/.bash_profile;
# Issue #145), which reads:
#   [ -r "<T>/home/.local/share/personal-multi-harness-workstation-configuration/paste-filter.sh" ] && . "<T>/home/.local/share/personal-multi-harness-workstation-configuration/paste-filter.sh"
# Then claude, codex and kiro-cli run through the wrapper, which cleans bracketed pastes before the
# CLI sees them and marks the session (PMHWC_PASTE_WRAPPER=1), so the prompt hook lets its prompts
# through. "command claude" (or codex, kiro-cli) runs a CLI without it, and the hook then checks.
claude() { "<NODE>" "<T>/tree/bin/mhw.js" paste-wrapper run --config "<T>/home/.local/share/personal-multi-harness-workstation-configuration/clipboard.conf" -- claude "$@"; }
codex() { "<NODE>" "<T>/tree/bin/mhw.js" paste-wrapper run --config "<T>/home/.local/share/personal-multi-harness-workstation-configuration/clipboard.conf" -- codex "$@"; }
kiro-cli() { "<NODE>" "<T>/tree/bin/mhw.js" paste-wrapper run --config "<T>/home/.local/share/personal-multi-harness-workstation-configuration/clipboard.conf" -- kiro-cli "$@"; }

